/* School and key-settings views. Commands remain the only progression writer. */
(function(r){'use strict';r.YouthSchoolUI=class {
 constructor({player,world,send,bindings,setBindings,storage,stop}){Object.assign(this,{player,world,send,bindings,setBindings,storage,stop});this.dialog=document.querySelector('#schoolPanel');this.keyDialog=document.querySelector('#keySettings');this.pending=null;
  document.querySelector('#closeSchools').onclick=()=>this.dialog.close();document.querySelector('#closeKeys').onclick=()=>{this.pending=null;this.keyDialog.close();};
  document.querySelector('#openKeys').onclick=()=>this.openKeys();document.querySelector('#openSchools').onclick=()=>this.open();
  document.querySelector('#schoolJoin').onclick=()=>send({type:'equip',path:document.querySelector('#schoolChoice').value});
  document.querySelector('#schoolChoice').onchange=e=>{send({type:'equip',path:e.target.value});};
  document.querySelector('#schoolPanelBody').addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.learn)send({type:'school-learn',skillId:b.dataset.learn});if(b.dataset.quest)send({type:'school-quest-accept',quest:b.dataset.quest});if(b.dataset.claim)send({type:'school-quest-claim'});});
  document.querySelector('#keyRows').addEventListener('click',e=>{const b=e.target.closest('[data-bind]');if(b){this.pending=b.dataset.bind;document.querySelector('#keyMessage').textContent='Press a key for '+YFKeys.labels[this.pending]+'. Escape cancels.';}});
  document.querySelector('#resetKeys').onclick=()=>{setBindings({...YFKeys.defaults});this.persist();this.renderKeys();};
  for(const select of [document.querySelector('#schoolChoice'),document.querySelector('#startSchool')])for(const s of YFSchoolData.schools){const o=document.createElement('option');o.value=s.id;o.textContent=s.name+' — '+s.weapon;select.appendChild(o);}
 }
 open(){this.stop?.();this.signature=null;this.dialog.showModal();this.render();}
 openKeys(){this.stop?.();this.pending=null;this.keyDialog.showModal();this.renderKeys();}
 persist(){document.querySelector('#keyMessage').textContent=YFKeys.save(this.storage(),this.bindings())?'Bindings saved in this browser.':'Bindings applied for this session; browser storage is unavailable.';}
 capture(e){if(!this.keyDialog.open)return false;if(this.pending){e.preventDefault();if(e.key==='Escape'){this.pending=null;document.querySelector('#keyMessage').textContent='Binding cancelled.';return true;}if(e.ctrlKey||e.metaKey||e.altKey)return true;const result=YFKeys.bind(this.bindings(),this.pending,e.key);if(!result.ok){document.querySelector('#keyMessage').textContent=result.message;return true;}this.setBindings(result.bindings);this.pending=null;this.persist();this.renderKeys();return true;}if(e.key==='Escape')this.keyDialog.close();return true;}
 renderKeys(){const rows=document.querySelector('#keyRows');rows.replaceChildren();for(const a of Object.keys(YFKeys.defaults)){const row=document.createElement('div'),label=document.createElement('span'),button=document.createElement('button');row.className='key-row';label.textContent=YFKeys.labels[a];button.dataset.bind=a;button.textContent=YFKeys.display(this.bindings()[a]);row.append(label,button);rows.appendChild(row);}document.querySelector('#comboKeys').textContent='Quick route: '+YFKeys.route(this.bindings())+' · Heavy route: '+YFKeys.route(this.bindings(),true)+'. Each key activates one skill; hits and timing still determine the combo.';}
 render(){if(!this.dialog.open)return;const p=this.player(),w=this.world(),s=YFSchoolData.get(p.path),rec=YFSchools.record(p),near=!!YFCity.activeNpc(w,p,'temple-trainer'),ready=near&&!p.action&&p.wanted===0&&p.jail===0;
  const signature=JSON.stringify([p.path,p.level,p.schoolProgress,ready,p.wanted,p.jail,YF.insideCity(p),!!p.action,p.cd.some(c=>c>0)]);if(signature===this.signature)return;this.signature=signature;
  document.querySelector('#schoolChoice').value=p.schoolProgress?.active||p.path;document.querySelector('#schoolChoice').disabled=!YF.insideCity(p)||p.wanted>0||!!p.action||p.cd.some(c=>c>0);
  document.querySelector('#schoolJoin').disabled=document.querySelector('#schoolChoice').disabled;
  document.querySelector('#schoolSummary').textContent=s.name+' · '+s.weapon+' — '+s.identity+' Level '+p.level+' / '+YFExperience.cap(p)+' (maximum 999). School reputation '+(rec?.reputation||0)+'.';
  const body=document.querySelector('#schoolPanelBody');body.replaceChildren();const note=document.createElement('p');note.textContent=near?'Master Dara represents the five schools. Complete quests, then learn eligible skills here.':'Visit Master Dara in Temple Ward to accept school quests, claim rewards and learn skills.';body.appendChild(note);
  for(const skill of YF.skillsFor(p)){const req=YFSchoolData.requirements[skill.index],row=document.createElement('div'),text=document.createElement('span'),button=document.createElement('button');row.className='lesson-row';text.textContent=skill.name+' · '+skill.range+' reach · '+skill.cost+' energy · Level '+req.level+', reputation '+req.reputation+(req.quest?', '+req.quest:'');button.dataset.learn=skill.id;button.textContent=YFSchools.canUse(p,skill)?'Learned':'Learn';button.disabled=!ready||YFSchools.canUse(p,skill)||!YFSchools.canLearn(p,skill);row.append(text,button);body.appendChild(row);}
  if(rec?.quest){const d=YFSchools.definition(p,rec.quest.id),line=document.createElement('p'),button=document.createElement('button');line.textContent=d.name+': '+rec.quest.count+' / '+d.goal+(d.kind==='trial'?' defeats; dummy combo '+(rec.quest.combo?'confirmed':'needed'):' '+(d.kind==='training'?'dummy strikes':'defeats'));button.dataset.claim='yes';button.textContent='Claim quest reward';button.disabled=!ready||!YFSchools.ready(p);body.append(line,button);}
  else for(const id of ['discipline','fieldwork','service','advancement']){const d=YFSchools.definition(p,id);if(!d||d.once&&rec.completed.includes(id))continue;const b=document.createElement('button');b.className='school-quest';b.dataset.quest=id;b.textContent=d.name+' · Level '+d.level+' · '+d.goal+' '+(d.kind==='training'?'dummy strikes':'defeats')+(d.kind==='trial'?' + dummy combo':'')+' · +'+d.rep+' reputation / '+d.xp+' XP';b.disabled=!ready||p.level<d.level||!!(d.requires&&!rec.completed.includes(d.requires));body.appendChild(b);}
  const advanced=document.createElement('p');advanced.className='small';advanced.textContent=['fist','spear'].includes(p.path)?'Hidden techniques still use Dara’s discovery challenge; Focus ultimates retain their combat requirements.':'This school starts with three ordinary techniques and a linked route. Hidden techniques and Focus ultimates are reserved for a later school update.';body.appendChild(advanced);
 }
};})(typeof globalThis!=='undefined'?globalThis:this);
